/**
* Removes duplicate elements from an array.
* @param {Array} arr - The input array.
* @return {number} - The number of unique elements in the array.
* The function modifies the input array in-place to contain only unique elements.
* The first part of the array will contain the unique elements, and the rest will be ignored.
* The function returns the count of unique elements.
*/
var removeDuplicates = function(nums) {
    let x = 0;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] > nums[x]) {
            x++;
            nums[x] = nums[i];
        }
    }
    return x + 1;
}; 

console.log(removeDuplicates([1, 2, 2, 3, 4, 4, 5]));
